// Two-bit saturating counter
module TopModule (
    input  clk,
    input  areset,
    input  train_valid,
    input  train_taken,
    output reg [1:0] state
);
    always @(posedge clk) begin
        if (areset) state <= 2'b01;
        else if (train_valid) begin
