// (train_valid = 0), the counter keeps its value unchanged. areset is a
// positive edge triggered asynchronous reset that resets the counter to
// weakly not-taken (2'b01). Output state[1:0] is the two-bit counter value.
// Assume all sequential logic is triggered on the positive edge of the clock.
module TopModule (
    input  clk,
    input  areset,
    input  train_valid,
    input  train_taken,
    output reg [1:0] state
);
    always @(posedge clk) begin
        if (areset) state <= 2'b01;
        else if (train_valid) begin
            if (train_taken) begin
                if (state < 2'b11) state <= state + 1;
            end else begin
                if (state > 2'b00) state <= state - 1;
            end
        end
    end
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  train_valid,
    input  train_taken,
    output reg [1:0] state
);
    always @(posedge clk) begin
        if (areset) state <= 2'b01;
        else if (train_valid) begin
            case (state)
                2'b00: state <= train_taken ? 2'b01 : 2'b00;
                2'b01: state <= train_taken ? 2'b10 : 2'b00;
                2'b10: state <= train_taken ? 2'b11 : 2'b01;
                2'b11: state <= train_taken ? 2'b11 : 2'b10;
            endcase
        end
    end
endmodule

